add_shortcode( 'product_sales', 'perfectpixel_product_sales_shortcode' );

function perfectpixel_product_sales_shortcode( $atts ) {
	$atts    = shortcode_atts( array( 'id' => 0 ), $atts );
	$product = wc_get_product( absint( $atts['id'] ) ? absint( $atts['id'] ) : get_the_ID() );
	if ( ! $product ) {
		return '';
	}
	return '<span class="perfectpixel-product-sales">' . esc_html( number_format_i18n( $product->get_total_sales() ) ) . '</span>';
}
